// 30-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in-
// line, added in an up-stage (registered in the same cycle) -> shorter per-
// -> shorter per-stage delay, higher Fmax. Same transfer function as the naïve
// register-to-register direct form (ALU-based MAC, no feedback).
module fir30_v5_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17, a18, a19, a20, a21, a22, a23, a24, a25, a26, a27, a28, a29;
    wire [47:0] y_up = a0 + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8 + a9 + a10 + a11 + a12 + a13 + a14 + a15 + a16 + a17 + a18 + a19 + a20 + a21 + a22 + a23 + a24 + a25 + a26 + a27 + a28 + a29;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'b0; a1 <= 24'b0; a2 <= 24'b0; a3 <= 24'b0; a4 <= 24'b0; a5 <= 24'b0; a6 <= 24'b0; a7 <= 24'b0; a8 <= 24'b0; a9 <= 24'b0; a10 <= 24'b0; a11 <= 24'b0; a12 <= 24'b0; a13 <= 24'b0; a14 <= 24'b0; a15 <= 24'b0; a16 <= 24'b0; a17 <= 24'b0; a18 <= 24'b0; a19 <= 24'b0; a20 <= 24'b0; a21 <= 24'b0; a22 <= 24'b0; a23 <= 24'b0; a24 <= 24'b0; a25 <= 24'b0; a26 <= 24'b0; a27 <= 24'b0; a28 <= 24'b0; a29 <= 24'b0; y <= 16'b0;
        end else begin
            a0 <= 48'd44 * x;
            a1 <= 48'd37 * x;
            a2 <= 48'd25 * x;
            a3 <= 48'd24 * x;
            a4 <= 48'd58 * x;
            a5 <= 48'd4 * x;
            a6 <= 48'd24 * x;
            a7 <= 48'd58 * x;
            a8 <= 48'd23 * x;
            a9 <= 48'd46 * x;
            a10 <= 48'd25 * x;
            a11 <= 48'd35 * x;
            a12 <= 48'd40 * x;
            a13 <= 48'd8 * x;
            a14 <= 48'd33 * x;
            a15 <= 48'd12 * x;
            a16 <= 48'd18 * x;
            a17 <= 48'd9 * x;
            a18 <= 48'd63 * x;
            a19 <= 48'd4 * x;
            a20 <= 48'd1 * x;
            a21 <= 48'd45 * x;
            a22 <= 48'd21 * x;
            a23 <= 48'd43 * x;
            a24 <= 48'd25 * x;
            a25 <= 48'd33 * x;
            a26 <= 48'd4 * x;
            a27 <= 48'd57 * x;
            a28 <= 48'd44 * x;
            a29 <= 48'd11 * x;
            y <= y_up[15:0];
        end
    end
endmodule
